import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.MalformedURLException;
import java.net.URI;
import java.net.URISyntaxException;

public class SecureWebApp {
    public static void main(String[] args) throws IOException {
        if (args.length == 0) {
            System.out.println("Usage: java SecureWebApp <url>");
            return;
        }

        String userInput = args[0];

        try {
            // Validate the input by parsing it as a URI first to ensure it's a valid format
            URI uri = new URI(userInput);

            // Check specifically that the scheme is 'http' or 'https' to prevent SSRF
            if (!"http".equalsIgnoreCase(uri.getScheme()) && 
               !"https".equalsIgnoreCase(uri.getScheme())) {
                throw new IllegalArgumentException("Only HTTP and HTTPS protocols are allowed.");
            }

            URL url = new URL(userInput);

            // Open a connection with a timeout to prevent hanging
            try (BufferedReader in = new BufferedReader(
                     new InputStreamReader(url.openStream()))) {
                String line;
                while ((line = in.readLine()) != null) {
                    System.out.println(line);
                }
            }
        } catch (URISyntaxException e) {
            System.err.println("Invalid URL format: " + userInput);
        }
    }
}
